use tax_us::state_tax_rate;

#[test]
fn rates_match_the_state_rules() {
    assert_eq!(state_tax_rate("CA"), 0.08);
    assert_eq!(state_tax_rate("OR"), 0.0);
    assert_eq!(state_tax_rate("NY"), 0.05);
}
